// AEOS Client Intake v0.1 — decision rules D1 and D2 from SPEC.md §3.
// Deterministic only. No model, no network call, no randomness.

const P1_TIMELINES = ['Immediately', 'This month'];
const P1_AUTHORITY = ['I control the budget', 'I influence the budget'];
const SLA_HOURS = { P1: 24, P2: 72 };

const out = [];

$input.all().forEach((item, index) => {
  const f = item.json;
  const submittedAt = new Date();

  // D1 — priority tier
  const timeline = (f['Timeline'] || '').trim();
  const budgetAuthority = (f['Budget authority'] || '').trim();
  const priority =
    P1_TIMELINES.includes(timeline) && P1_AUTHORITY.includes(budgetAuthority)
      ? 'P1'
      : 'P2';

  // D2 — response deadline
  const slaDueAt = new Date(
    submittedAt.getTime() + SLA_HOURS[priority] * 60 * 60 * 1000,
  );

  out.push({
    json: {
      submission_id: `AEOS-${$execution.id}-${index + 1}`,
      submitted_at: submittedAt.toISOString(),
      full_name: (f['Full name'] || '').trim(),
      work_email: (f['Work email'] || '').trim(),
      phone: (f['Phone'] || '').trim(),
      organization: (f['Organization'] || '').trim(),
      role: (f['Role'] || '').trim(),
      students_served: (f['Students served'] || '').trim(),
      problem_statement: (f['What problem are you trying to solve?'] || '').trim(),
      timeline,
      budget_authority: budgetAuthority,
      priority,
      sla_due_at: slaDueAt.toISOString(),
      status: 'New',
      owner: '',
      first_contact_at: '',
      outcome: '',
      notes: '',
    },
  });
});

return out;

